// mathUtils.js
export default function pomnoz(a, b) { return a * b; }

// inny-plik.js
import razy from "./mathUtils.js";
console.log(razy(8, 9)); // 72

// stringUtils.js
export default function odwroc(str) {
  return [...str].reverse().join("");
}

// inny-plik.js
import odwrocString from "./stringUtils.js";
console.log(odwrocString("kurs")); // "sruk"

// KontoBankowe.js
export default class Konto {
  constructor(saldo) {
    this.saldo = saldo;
  }
}

// inny-plik.js
import KontoBankowe from "./KontoBankowe.js";
const konto = new KontoBankowe(500);
console.log(konto.saldo); // 500

// Witaj.js
export default (name) => `Witaj, ${name}!`;

// inny-plik.js
import powitanie from "./Witaj.js";
console.log(powitanie("Ala")); // "Witaj, Ala!"

// Eksport domyslny NIE JEST powiazany z zadna konkretna nazwa na poziomie
// modulu - jest traktowany jako JEDYNA, 'glowna' wartosc udostepniana przez
// plik. Dlatego import po stronie odbiorcy MOZE go nazwac dowolnie
// (import cokolwiek from './plik.js') - silnik JS wie, ze chodzi o TA
// JEDYNA wartosc, bez potrzeby 'wyszukiwania' jej po konkretnej nazwie.
//
// Import nazwany dziala inaczej - wymaga DOKLADNEJ zgodnosci z nazwa
// uzyta po export w pliku zrodlowym (np. export function dodaj musi byc
// importowane jako { dodaj }, chyba ze uzyjemy aliasu 'as'), poniewaz
// moze byc wiele nazwanych eksportow w jednym pliku - silnik JS musi
// 'wiedziec', KTORY z nich chcesz zaimportowac.

// Logger.js
export default function log(wiadomosc) {
  return `[LOG] ${wiadomosc}`;
}

// plikA.js
import logujA from "./Logger.js";
console.log(logujA("test")); // "[LOG] test"

// plikB.js
import logujB from "./Logger.js";
console.log(logujB("test")); // "[LOG] test" - identyczny wynik, inna nazwa

// Plik moze miec tylko JEDEN export default, poniewaz reprezentuje on
// 'JEDNA, GLOWNA' rzecz, ktora ten plik udostepnia - koncepcyjnie ma to
// sens, ze plik ma JEDNA 'domyslna tozsamosc' (np. jeden komponent React,
// jedna glowna klasa/funkcje).
//
// Proba uzycia export default wiecej niz raz w tym samym pliku jest
// bledem skladniowym - silnik JS nie wiedzialby, KTORY z wielu 'domyslnych'
// eksportow ma zostac uzyty przy imporcie bez klamer (import cokolwiek
// from './plik.js').
//
// Nazwanych eksportow moze byc wiele, poniewaz kazdy z nich ma WLASNA,
// unikalna nazwe - nie ma ryzyka niejednoznacznosci.

// powitanie.js
export default function powitaj(imie) {
  return "Czesc, " + imie;
}

// main.js
import przywitaj from "./powitanie.js";
console.log(przywitaj("Ola")); // -> Czesc, Ola

// narzedzia.js
export default {
  dodaj: (a, b) => a + b,
  odejmij: (a, b) => a - b,
};

// main.js
import n from "./narzedzia.js";
console.log(n.dodaj(5, 3), n.odejmij(5, 3)); // -> 8 2

// a.js
export default function f() { return 1; }

// b.js
import pierwsza from "./a.js";
export { pierwsza };

// c.js
import druga from "./a.js";
export { druga };

// main.js
import { pierwsza } from "./b.js";
import { druga } from "./c.js";
console.log(pierwsza === druga); // -> true

// a.js
export default function () {}

// main.js
import f from "./a.js";
console.log(f.name); // -> default

// Licznik.js
export default class Licznik {
  n = 0;
  zwieksz() { this.n++; }
}

// main.js
import Counter from "./Licznik.js";
const a = new Counter();
const b = new Counter();
a.zwieksz();
console.log(a.n, b.n); // -> 1 0

// a.js
export default function pomnoz(a, b) { return a * b; }

// main.js
import razy from "./a.js";
console.log(typeof pomnoz, typeof razy); // -> undefined function

// stan.js
export default { licznik: 0 };

// a.js
import stan from "./stan.js";
stan.licznik++;

// b.js
import stan from "./stan.js";
stan.licznik++;

// main.js
import stan from "./stan.js";
import "./a.js";
import "./b.js";
console.log(stan.licznik); // -> 2

// a.js
export default 42;

// main.js
import { default as x } from "./a.js";
import y from "./a.js";
console.log(x, y, x === y); // -> 42 42 true

// a.js
let x = 1;
export default x;
export { x as zywe };
export function zmien() { x = 2; }

// main.js
import domyslny, { zywe, zmien } from "./a.js";
zmien();
console.log(domyslny, zywe); // -> 1 2

// stale.js
export default ["pon", "wt", "sr", "czw", "pt", "sob", "nd"];

// main.js
import dni from "./stale.js";
console.log(dni.length, dni[0]); // -> 7 pon

// Przycisk.js
export default function Przycisk({ tekst }) {
  return "<button>" + tekst + "</button>";
}

// main.js
import Przycisk from "./Przycisk.js";
console.log(Przycisk({ tekst: "Zapisz" }));
console.log(Przycisk({ tekst: "Anuluj" }));

// podatek.js
export default 0.23;

// main.js
import stawka from "./podatek.js";
console.log(100 * (1 + stawka)); // -> 123

// a.js
export default "jeden";
// export default "dwa"; // -> SyntaxError: Duplicate export of 'default'
export const nazwany = "moge miec wiele nazwanych";

// main.js
import domyslny, { nazwany } from "./a.js";
console.log(domyslny, nazwany); // -> jeden moge miec wiele nazwanych

// a.js
export const nazwany = 1;
export default "domyslny";

// main.js
// import x from "./a.js"; // gdyby a.js nie mial "export default" -> SyntaxError
import x, { nazwany } from "./a.js";
console.log(x, nazwany); // -> domyslny 1

// a.js
export default () => "ok";

// main.js
import f from "./a.js";
console.log(f(), f.name); // -> ok default
// funkcja jest anonimowa - silnik nadaje jej nazwe "default"

// logger.js
export default function log(wiadomosc) {
  return "[log] " + wiadomosc;
}

// a.js
import logujA from "./logger.js";
export const wynikA = logujA("a");

// b.js
import logujB from "./logger.js";
export const wynikB = logujB("b");

// main.js
import { wynikA } from "./a.js";
import { wynikB } from "./b.js";
console.log(wynikA, wynikB); // -> [log] a [log] b

// matematyka.js
export default {
  dodaj: (a, b) => a + b,
  pomnoz: (a, b) => a * b,
};

// main.js
import matematyka from "./matematyka.js";
const { dodaj, pomnoz } = matematyka;
console.log(dodaj(2, 3), pomnoz(2, 3)); // -> 5 6

// a.js
const nazwa = "modul";
export default nazwa;

// main.js
import wartosc from "./a.js";
console.log(wartosc); // -> modul

// osoba.js
export default class Osoba {}

// main.js
import Uzytkownik from "./osoba.js";
const u = new Uzytkownik();
console.log(Uzytkownik.name, u instanceof Uzytkownik); // -> Osoba true

// fabryka.js
let ostatnie = 0;
export default function stworz(nazwa) {
  ostatnie++;
  return { id: ostatnie, nazwa };
}

// main.js
import stworz from "./fabryka.js";
console.log(stworz("a").id, stworz("b").id, stworz("c").id); // -> 1 2 3

// a.js
function f() { return "f"; }
export default f;
export const g = () => "g";
export { f as h };

// main.js
import domyslna, { g, h } from "./a.js";
console.log(domyslna(), g(), h(), domyslna === h); // -> f g f true

// Naglowek.js
export default function Naglowek() {
  return "<h1>Witaj</h1>";
}

// App.js
import Naglowek from "./Naglowek.js";
export default function App() {
  return "<div>" + Naglowek() + "</div>";
}

// main.js
import App from "./App.js";
console.log(App()); // -> <div><h1>Witaj</h1></div>

// formatujCene.js
export default function formatujCene(cena) {
  return cena.toFixed(2) + " zł";
}

// index.js
export { default as formatujCene } from "./formatujCene.js";

// main.js
import { formatujCene } from "./index.js";
console.log(formatujCene(12.5)); // -> "12.50 zł"

